const app=document.querySelector('#app'),dialog=document.querySelector('#dialog'),toastEl=document.querySelector('#toast');
const state={user:null,csrf:'',workspace:null,page:null,run:null,filter:'all',busy:false,menuOpen:false};
const e=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const icons={overview:'M3 3h7v7H3z M14 3h7v7h-7z M3 14h7v7H3z M14 14h7v7h-7z',audit:'M9 3h6v4H9z M6 5H4v16h16V5h-2 M8 12l2 2 5-5 M8 18h8',connections:'M8 3H5v7h3 M16 3h3v7h-3 M5 7h14 M12 10v11 M8 18h8',explorer:'M8 6l-6 6 6 6 M16 6l6 6-6 6 M14 3l-4 18',monitor:'M3 4v16h18 M5 14l4-5 4 4 6-8',standards:'M4 3h12l4 4v14H4z M14 3v6h6 M8 13h8 M8 17h6',reports:'M4 3h16v18H4z M8 8h8 M8 12h8 M8 16h5',gate:'M12 2l8 4v6c0 5-8 10-8 10S4 17 4 12V6z M8 12l3 3 5-6',activity:'M3 12h4l3-8 4 16 3-8h4',arrow:'M5 12h14 M14 7l5 5-5 5',plus:'M12 4v16 M4 12h16',play:'M8 4l13 8-13 8z',download:'M12 3v12 M7 10l5 5 5-5 M4 17v4h16v-4',info:'M12 8v1 M12 12v5 M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0',check:'M5 12l4 4L20 5',close:'M5 5l14 14 M5 19L19 5',clock:'M12 7v5l4 2 M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0',chevron:'M9 5l7 7-7 7',logout:'M9 3H4v18h5 M12 12h10 M17 7l5 5-5 5',search:'M21 21l-6-6 M17 10a7 7 0 1 1-14 0 7 7 0 0 1 14 0'};
icons.diagnostics=icons.gate;
const icon=(name)=>`<svg class="icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${icons[name]||icons.info}"/></svg>`;
const badge=(text,kind=text)=>`<span class="badge ${e(String(kind).toLowerCase())}">${e(String(text).replaceAll('_',' '))}</span>`;
const date=v=>v?new Date(v).toLocaleString('en-GB',{month:'short',day:'numeric',hour:'2-digit',minute:'2-digit'}):'Not recorded';
const ago=v=>v?date(v):'Not measured';
const button=(text,action,cls='',data='')=>`<button class="btn ${cls}" data-action="${action}" ${data}>${text}</button>`;
const empty=(title,text,action='')=>`<div class="empty"><div class="empty-icon">${icon('audit')}</div><h3>${title}</h3><p>${text}</p>${action}</div>`;
function toast(s){toastEl.textContent=s;toastEl.style.display='block';clearTimeout(toast.timer);toast.timer=setTimeout(()=>toastEl.style.display='none',5500)}
async function api(url,options={}){const r=await fetch(url,{...options,headers:{'Content-Type':'application/json','X-CSRF-Token':state.csrf,...options.headers},body:options.body===undefined?undefined:JSON.stringify(options.body)});const data=await r.json();if(!r.ok){if(r.status===401&&url!='/api/login'){clearSession();login()}throw Error(data.error||'Request failed')}return data}
function modal(title,body){document.querySelector('#dialog-body').innerHTML=`<div class="dialog-head"><h2>${title}</h2>${button(icon('close'),'close','quiet','aria-label="Close dialog"')}</div><div class="dialog-content">${body}</div>`;dialog.showModal()}
function head(eyebrow,title,description,actions=''){return `<header class="pagehead"><div><h1>${title}</h1></div><div class="buttons">${actions}</div></header>`}
function notice(title,text,amber=false){return `<div class="notice ${amber?'amber':''}">${icon('info')}<div><b>${title}</b><p>${text}</p></div></div>`}
const rolePolicies={
 operator:{title:'Operator workspace',home:'overview',pages:['overview','audit','connections','explorer','oversight','monitor','reports','standards','gate','activity','diagnostics']},
 bank:{title:'Bank engineer workspace',home:'audit',pages:['audit','connections','monitor','reports','standards','gate','activity']},
 tpp:{title:'TPP developer workspace',home:'explorer',pages:['explorer','activity']},
 reviewer:{title:'Oversight workspace',home:'oversight',pages:['oversight','audit','monitor','reports','activity']},
 standards:{title:'Standards reviewer workspace',home:'standards',pages:['standards','activity']}
};
const policy=()=>rolePolicies[state.user?.role]||{title:'Restricted workspace',home:'activity',pages:['activity']};
const roleNav=()=>policy().pages.map(key=>nav.find(([id])=>id===key)).filter(Boolean);
function activateSession(result){state.measurementFilters={connection:'',operation:''};state.measurementCollapsed={};state.user=result.user;state.csrf=result.csrf;state.workspace=null;state.gringott=null;state.run=null;state.filter='all';state.page=policy().home;}
function clearSession(){state.measurementFilters={connection:'',operation:''};state.measurementCollapsed={};state.user=null;state.csrf='';state.gringott=null;state.availability=[];state.workspace=null;state.run=null;state.filter='all';state.page=null;if(dialog.open)dialog.close();}
function navigate(page){state.menuOpen=false;state.page=policy().pages.includes(page)?page:policy().home;state.filter='all';render();globalThis.window?.scrollTo({top:0,left:0,behavior:'instant'});}
const canRun=()=>['operator','bank'].includes(state.user.role);
const canReview=()=>['operator','standards'].includes(state.user.role);
const nav=[['diagnostics','System diagnostics'],['overview','Overview'],['audit','Audit center'],['connections','Connections'],['explorer','TPP explorer'],['oversight','Oversight dashboard'],['monitor','Monitoring'],['reports','Reports'],['standards','Standards & rules'],['gate','Release gates'],['activity','Activity log']];
function setMenu(open){
 state.menuOpen=open;
 const shell=document.querySelector('.workspace-shell'),toggle=document.querySelector('.topbar .menu-toggle'),menu=document.querySelector('#workspace-menu');
 if(!shell)return;
 shell.classList.toggle('menu-open',open);menu.inert=!open;document.querySelectorAll('.menu-toggle').forEach(control=>{control.setAttribute('aria-expanded',String(open));control.setAttribute('aria-label',open?'Close menu':'Open menu')});
 if(!open)toggle.focus();
}
document.addEventListener('keydown',ev=>{if(ev.key==='Escape'&&state.menuOpen)setMenu(false)});
function shell(body){const w=state.workspace;const allowedNav=roleNav();const workNav=allowedNav.filter(([k])=>!['standards','gate','activity','diagnostics'].includes(k));const governNav=allowedNav.filter(([k])=>['standards','gate','activity','diagnostics'].includes(k));app.innerHTML=`<div class="shell workspace-shell ${state.menuOpen?'menu-open':''}"><aside class="sidebar" id="workspace-menu" aria-label="Workspace navigation" ${state.menuOpen?'':'inert'}><div class="sidebar-header"><button class="menu-toggle" data-action="toggle-menu" aria-label="${state.menuOpen?'Close menu':'Open menu'}" aria-expanded="${state.menuOpen}" aria-controls="workspace-menu"><svg class="hamburger-bars" width="18" height="18" viewBox="0 0 18 18" aria-hidden="true"><path d="M1 3h16v2H1z M1 8h16v2H1z M1 13h16v2H1z" fill="currentColor"/></svg></button><button class="brand brand-home" data-nav="overview" aria-label="GeoBridge — go to overview"><img class="brand-mark brand-logo" src="/logo.png" alt="" width="40" height="40"><span>GeoBridge<small>Open banking assurance</small></span></button></div><div class="nav-label">${e(policy().title.toUpperCase())}</div>${workNav.map(([k,t])=>`<button class="nav-item ${state.page===k?'active':''}" data-nav="${k}">${icon(k)}${t}</button>`).join('')}${governNav.length?'<div class="nav-label">GOVERNANCE</div>':''}${governNav.map(([k,t])=>`<button class="nav-item ${state.page===k?'active':''}" data-nav="${k}">${icon(k)}${t}</button>`).join('')}<div class="side-foot"><div class="local-tag"><i class="dot"></i> Demo environment</div></div></aside><button class="menu-backdrop" data-action="close-menu" aria-label="Close menu" tabindex="-1"></button><main class="main"><div class="topbar"><button class="menu-toggle" data-action="toggle-menu" aria-label="${state.menuOpen?'Close menu':'Open menu'}" aria-expanded="${state.menuOpen}" aria-controls="workspace-menu"><svg class="hamburger-bars" width="18" height="18" viewBox="0 0 18 18" aria-hidden="true"><path d="M1 3h16v2H1z M1 8h16v2H1z M1 13h16v2H1z" fill="currentColor"/></svg></button><button class="brand brand-home" data-nav="overview" aria-label="GeoBridge — go to overview"><img class="brand-mark brand-logo" src="/logo.png" alt="" width="40" height="40"><span>GeoBridge<small>Open banking assurance</small></span></button><div class="buttons"><span class="badge">SYNTHETIC ONLY</span><div class="userbox"><div class="avatar">${e(state.user.name.split(' ').map(x=>x[0]).slice(0,2).join(''))}</div><div><strong>${e(state.user.name)}</strong><small>${e(policy().title)}</small></div></div>${button(icon('logout'),'logout','quiet','aria-label="Sign out"')}</div></div><div class="content">${body}<div class="footer-line"><span>GeoBridge</span><span>Build 0.1.0 · ${w?.ai.configured?'Live AI configured':'AI template fallback'} · No certification claims</span></div></div></main></div>`}
function login(){
 const eye=shown=>'<svg class="icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M2 12s3.5-7 10-7 10 7 10 7-3.5 7-10 7S2 12 2 12Z"/><circle cx="12" cy="12" r="3"/>'+(!shown?'<path d="M3 3l18 18"/>':'')+'</svg>';
 app.innerHTML=`<div class="login login-simple"><header class="login-brand"><div class="brand"><img class="brand-mark brand-logo" src="/logo-login.png" alt="" width="40" height="40"><span>GeoBridge<small>Open banking assurance</small></span></div></header><section class="login-form"><div class="login-form-inner"><h2>Welcome to GeoBridge</h2><p>Check APIs against selected standards, monitor availability, and connect through one common interface.</p><form id="login-form"><div class="field"><label for="username">Username</label><input id="username" name="username" autocomplete="username" placeholder="e.g. operator" required></div><div class="field"><label for="password">Password</label><div class="password-field"><input id="password" name="password" type="password" autocomplete="current-password" placeholder="Your password" required><button class="password-toggle" id="password-toggle" type="button" aria-label="Show password" aria-controls="password" aria-pressed="false">${eye(false)}</button></div></div><button class="btn primary" id="login-submit" type="submit">Sign in ${icon('arrow')}</button><div class="error" id="login-error" role="alert"></div></form><div class="divider"></div><p class="login-help">Use the demo credentials provided by the team</p></div></section></div>`;
 const form=document.querySelector('#login-form'),submit=document.querySelector('#login-submit'),error=document.querySelector('#login-error'),password=document.querySelector('#password'),toggle=document.querySelector('#password-toggle');
 toggle.onclick=()=>{const shown=password.type==='password';password.type=shown?'text':'password';toggle.innerHTML=eye(shown);toggle.setAttribute('aria-label',shown?'Hide password':'Show password');toggle.setAttribute('aria-pressed',String(shown))};
 let submitting=false;
 form.onsubmit=async ev=>{
  ev.preventDefault();if(submitting)return;
  const b=Object.fromEntries(new FormData(form));
  submitting=true;submit.disabled=true;form.setAttribute('aria-busy','true');error.textContent='';
  submit.innerHTML='<span class="login-loading" role="status"><span class="sr-only">Signing in…</span><span class="login-dots" aria-hidden="true"><i></i><i></i><i></i></span></span>';
  try{const result=await api('/api/login',{method:'POST',body:b});activateSession(result);await refresh()}
  catch(err){if(error.isConnected)error.textContent=err.message;else toast(err.message)}
  finally{submitting=false;submit.disabled=false;form.removeAttribute('aria-busy');submit.innerHTML=`Sign in ${icon('arrow')}`}
 };
}
async function refresh(){state.workspace=await api('/api/workspace');state.availability=[];if(['operator','bank','reviewer'].includes(state.user.role)){const x=await api('/api/availability');state.availability=x.targets||[]}render()}
function metric(label,value,note,ic='monitor',highlight=false,target=''){const linked=target&&policy().pages.includes(target);return `<div class="card metric ${highlight?'highlight':''}"><div class="label">${label}${linked?`<button class="metric-link" data-nav="${target}" aria-label="Open ${e(target==='audit'?'audit center':target==='standards'?'standards and rules':target==='monitor'?'monitoring':target)}">${icon(ic)}</button>`:icon(ic)}</div><div class="value">${value}</div><div class="note">${note}</div></div>`}
function overview(){
 const w=state.workspace,completed=w.runs.filter(r=>r.status==='completed'),latest=completed[0],drafts=w.rules.filter(r=>r.status==='draft'),approved=w.rules.filter(r=>r.status==='approved');
 return '<header class="pagehead operator-overview"><div><h1>Overview</h1><p>Connection status, recent audit results, and standards awaiting review.</p></div><div class="buttons">'+(canRun()?button(icon('play')+' Run bank API audit','new-run','primary'):'')+'</div></header>'+`<div class="grid four">${metric('Registered connections',w.connections.length,'View configured connections','connections',false,'connections')}${metric('Completed audits',completed.length,latest?'Latest: '+date(latest.finishedAt):'No completed audits','audit',false,'audit')}${metric('Approved rules',approved.length+'/'+w.rules.length,drafts.length+' awaiting review','standards',false,'standards')}${metric('Bank monitoring','—','No live bank observations','monitor',true,'monitor')}</div><div class="card space"><div class="card-head"><h2>Recent audit results</h2>${button('All audits '+icon('arrow'),'nav-audit','quiet')}</div>${runTable(w.runs.slice(0,5))}</div><div class="grid two space"><div class="card"><div class="card-head"><h2>Connections</h2>${button('Manage connections '+icon('arrow'),'nav-connections','quiet')}</div>${w.connections.length?'<div class="table-wrap"><table><thead><tr><th>Connection</th><th>Profile</th><th>Status</th></tr></thead><tbody>'+w.connections.slice(0,5).map(c=>'<tr><td>'+e(c.name)+'</td><td>'+e(c.profile||'Not selected')+'</td><td>'+badge(c.status)+'</td></tr>').join('')+'</tbody></table></div>':'<div class="pad"><p>No connections registered.</p></div>'}</div><div class="card"><div class="card-head"><h2>Standards review</h2>${button('Open rules '+icon('arrow'),'nav-standards','quiet')}</div><div class="pad"><div class="review-counts"><div><strong>${drafts.length}</strong><span>Awaiting review</span></div><div><strong>${approved.length}</strong><span>Approved</span></div></div><p>${drafts.length?'Review draft rules and their source documents before activation.':'No draft rules awaiting review.'}</p></div></div></div><div class="card space"><div class="card-head"><h2>Latest audit results by check category</h2>${latest?badge(latest.status):badge('No completed audit')}</div><div class="pad">${latest?['compatibility','reliability','latency','security'].map(layer=>{const results=(latest.results||[]).filter(r=>r.layer===layer||r.category===layer);return '<div class="layer-row"><label>'+e(layer[0].toUpperCase()+layer.slice(1))+'</label><span>'+ (results.length?results.filter(r=>r.verdict==='PASS').length+' passed / '+results.length+' checks':'No checks recorded')+'</span></div>'}).join(''):'<p>Category results appear after an audit completes.</p>'}</div></div>`;
}
function runTable(runs){if(!runs.length)return empty(canRun()?'No audits recorded':'No audit evidence in your scope',canRun()?'Run a bank API audit or review saved API responses.':'Authorized bank diagnostics will appear after runs are shared with your role.',canRun()?button('Run bank API audit','new-run','primary'):'');return `<div class="table-wrap"><table><thead><tr><th>Audit</th><th>Evidence</th><th>Status</th><th>Created</th><th></th></tr></thead><tbody>${runs.map(r=>`<tr class="clickable" data-run="${r.id}"><td><b>${e(r.name)}</b><small>${e(r.profile)}</small></td><td>${badge(r.evidenceMode||r.kind)}</td><td>${badge(r.status)}</td><td class="subtle">${date(r.createdAt)}</td><td>${icon('chevron')}</td></tr>`).join('')}</tbody></table></div>`}
function audit(){
 const runs=state.workspace.runs.filter(r=>r.kind!=='platform');
 return head('','Audit center','',canRun()?button('Review saved API responses','review-saved')+button(icon('play')+' Run bank API audit','new-run','primary'):button('Compare runs','compare-runs'))+
 '<p class="audit-summary">Run requests against a configured bank connection, or review saved responses without sending new requests.</p><div class="card space"><div class="card-head"><h2>Bank audit history</h2>'+button('Compare runs','compare-runs','small')+'</div>'+runTable(runs)+'</div>';
}
function diagnostics(){
 if(state.user.role!=='operator')return '';
 const runs=state.workspace.diagnosticsRuns||[];
 return head('','System diagnostics','',button('Run self-checks','run-platform','primary'))+'<p class="audit-summary">Internal GeoBridge checks for signing, access controls, mapping, and measurement calculations. These do not test bank APIs.</p><div class="card space"><div class="card-head"><h2>Self-check results</h2></div>'+(runs.length?runTable(runs):empty('No self-checks recorded','Select Run self-checks to test GeoBridge.'))+'</div>';
}
function oversight(){
 const w=state.workspace,runs=w.runs.filter(r=>r.status==='completed'&&r.kind!=='platform');
 const latest=new Map();for(const r of runs)if(!latest.has(r.connectionId||r.packId||r.id))latest.set(r.connectionId||r.packId||r.id,r);
 const cohort=[...latest.values()];const count=k=>cohort.reduce((n,r)=>n+(r.counts?.[k]||0),0);
 return head('AUTHORIZED BANK SCOPES','Oversight dashboard','Compare observed quality, inspect deviations and understand coverage. This is a read-only review workspace.')+
 `<div class="grid four">${metric('Visible bank connections',w.connections.length,'Explicit development review scope','connections')}${metric('Evidence runs',runs.length,'Platform self-tests excluded','audit')}${metric('Failed selected checks',count('FAIL'),'Not an overall bank rating','reports')}${metric('Unresolved checks',count('BLOCKED')+count('NEEDS_REVIEW')+count('NOT_ASSESSED'),'Latest visible evidence per target','standards')}</div><div class="space">${notice('Evidence types','Results identify whether they use fixtures or captured responses. Production bank measurements are not available.')}</div><div class="card space"><div class="card-head"><div><h2>Coverage & findings</h2><p>Read original expectations and results; raw account and transaction payloads are not shared.</p></div>${button('Open evidence','nav-audit')}</div>${runTable(runs)}</div><div class="grid two space"><div class="panel-summary"><h2>Monitoring history</h2><p>Use the same profile, operation and measurement method. Unknown observations stay unknown; short probes do not establish monthly uptime.</p><div class="spacer"></div>${button('Review quality & history','nav-monitor')}</div><div class="card pad"><h2>Findings and reports</h2><p>Inspect source locators, expected vs observed behavior and remediation guidance. Bank testing and changes remain with the authorized bank team.</p><div class="spacer"></div>${button('Open reports','nav-reports')}</div></div>`;
}
function connections(){return head('AUTHORIZED TARGETS ONLY','Connections','Register a sandbox contract or execute a configured synthetic adapter. Real-bank onboarding remains separate.',canRun()?button(icon('plus')+' Register connection','new-connection','primary'):'')+notice('Connection setup','Upload OpenAPI specifications for static checks. Configured mock adapters support HTTP audits with simulated consent. Real-bank access requires separate authorization and certificates.')+`<div class="grid two space">${state.workspace.connections.map(c=>`<div class="card"><div class="card-head"><div><h2>${e(c.name)}</h2><p>${e(c.environment)} · ${e(c.tenant)}</p></div>${badge(c.status,'blocked')}</div><div class="pad"><div class="profile-chip">${e(state.workspace.profiles.find(p=>p.id===c.profile)?.name||c.profile)}</div><div class="chip-list">${Object.entries(c.capabilities).map(([k,v])=>`<span class="chip">${e(k)} · ${e(v)}</span>`).join('')}</div><div class="divider"></div><p class="smalltext">${c.baseUrl?e(c.baseUrl):'Sandbox URL not supplied'}</p><p class="mono" style="margin-top:10px">Spec ${c.specHash?e(c.specHash.slice(0,20))+'…':'not uploaded'}</p><div class="buttons space">${canRun()?button('Upload OpenAPI','upload-spec','small',`data-id="${c.id}"`)+(c.specHash?button('Review specification','run-spec','small',`data-id="${c.id}"`):'')+button(c.status==='mock_configured'?'Run '+e(c.name)+' HTTP audit':'Check readiness','readiness','small',`data-id="${c.id}"`):''}</div></div></div>`).join('')||`<div class="card">${empty('No connections in your scope','Your role can only see explicitly authorized private connection details.')}</div>`}</div>`}
const mappingSamples={accounts:{accounts:[{resourceId:'synthetic-account-01',currency:'GEL',displayName:'Synthetic account',cashAccountType:'CACC'}]},balances:{balances:[{balanceAmount:{amount:'1250.50',currency:'GEL'},balanceType:'interimAvailable',referenceDate:'2026-10-20'},{balanceAmount:{amount:'1300.50',currency:'GEL'},balanceType:'interimBooked',referenceDate:'2026-10-20'}]},transactions:{transactions:{booked:[{transactionId:'synthetic-01',transactionAmount:{amount:'-25.50',currency:'GEL'},bookingDate:'2026-10-20'}],pending:[{transactionId:'synthetic-02',transactionAmount:{amount:'-10.00',currency:'GEL'}}]}}};
function explorer(){const catalog=state.workspace.catalog||[];return head('ONE CONTRACT · EXPLICIT ADAPTERS','TPP explorer','Understand the common response format before connecting an authorized bank.')+notice('Test data and mapping','Use mock connections for HTTP requests or preview how JSON responses map to the common format. Real-bank data is not connected.')+gringottExplorer()+`<div class="card space"><div class="card-head"><div><h2>Supported connections</h2><p>Published capabilities only. Private bank configuration is not shared.</p></div></div>${catalog.length?`<div class="table-wrap"><table><thead><tr><th>Connection</th><th>Status</th><th>Capabilities</th></tr></thead><tbody>${catalog.map(c=>`<tr><td>${e(c.name)}</td><td>${badge(c.status,'blocked')}</td><td>${Object.entries(c.capabilities||{}).map(([k,v])=>e(k)+': '+e(v)).join(' · ')}</td></tr>`).join('')}</tbody></table></div>`:empty('No published connections yet','Bank adapters and authorization must be verified before live operations become available.')}</div><div class="grid two space"><div class="card"><div class="card-head"><div><h2>Common contract preview</h2><p>Validate an API response and convert it to the common format.</p></div>${badge('Synthetic preview')}</div><div class="pad"><div class="field"><label for="mapping-operation">Operation</label><select id="mapping-operation"><option value="balances">Get balances</option><option value="accounts">List accounts</option><option value="transactions">List transactions</option></select></div><div class="field"><label for="mapping-json">Original synthetic response</label><textarea id="mapping-json" style="min-height:290px">${e(JSON.stringify(mappingSamples.balances,null,2))}</textarea></div><div class="buttons">${button(icon('play')+' Validate & normalize','normalize','primary')}${button('Insert missing-currency fault','mapping-fault','small')}</div></div></div><div class="card"><div class="card-head"><div><h2>GeoBridge response</h2><p>Normalized response or validation errors.</p></div></div><div class="pad" id="mapping-result">${empty('No mapping result yet','Enter a response and select Validate & normalize.')}</div></div></div><div class="card space"><div class="card-head"><h2>Bank API access</h2>${badge('Not connected','blocked')}</div><div class="pad"><div class="grid two"><div><h3>Proposed common endpoints</h3><a class="btn small" href="/api/contract" target="_blank" rel="noopener">Common OpenAPI JSON</a><pre class="code light">GET /bridge/v1/connections
GET /bridge/v1/connections/{id}/accounts
GET /bridge/v1/connections/{id}/accounts/{id}/balances
GET /bridge/v1/connections/{id}/accounts/{id}/transactions</pre></div><div><h3>Required connection setup</h3><p>Each connection needs a bank-specific adapter, the TPP identity, supported permissions and an authoritative valid consent. Current bank requests return <code>BANK_NOT_CONNECTED</code>.</p><div class="spacer"></div>${['tpp','operator'].includes(state.user.role)?button('Check bank API response','bridge-check'):badge('TPP login required')}</div></div><div id="bridge-result"></div></div></div>`}
function monitoring(){const w=state.workspace;const captures=w.runs.filter(r=>r.status==='completed'&&r.metrics?.some(m=>m.attempts));return head('MEASURE WHAT YOU ACTUALLY OBSERVE','Monitoring','Schedules, observation windows and per-operation measurements—with clear freshness.',canRun()?button(icon('plus')+' Add schedule','new-schedule','primary'):'')+availabilityPanel()+`<div class="grid three">${metric('Bank probe availability','—','No live bank probe history in your scope')}${metric('Bank response time','—','No live latency observations')}${metric('Active schedules',w.schedules.length,'Runs while the local server is running','clock')}</div><div class="card space"><div class="card-head"><div><h2>Observation history</h2><p>Unknown intervals stay grey. No monthly uptime is inferred.</p></div>${badge('No live observations')}</div><div class="pad"><div class="timeline">${Array.from({length:60},()=>'<i title="No observation"></i>').join('')}</div><div class="legend"><span class="good">Successful probe</span><span class="bad">Failed probe</span><span>No observation</span></div><div class="spacer"></div><p class="smalltext">Connect a bank adapter before enabling actual probes. Replaying captured evidence does not create new bank availability observations.</p></div></div>${canRun()?`<div class="card space"><div class="card-head"><h2>Scheduled jobs</h2></div>${w.schedules.length?`<div class="table-wrap"><table><thead><tr><th>Job</th><th>Interval</th><th>Next run</th><th>Last result</th><th></th></tr></thead><tbody>${w.schedules.map(s=>`<tr><td>${e(s.label)}</td><td>${s.minutes} min</td><td>${date(s.nextRun)}</td><td>${e(s.lastError|| (s.lastRun?'Scheduled successfully':'Waiting'))}</td><td>${canRun()?button('Remove','delete-schedule','small',`data-id="${s.id}"`):''}</td></tr>`).join('')}</tbody></table></div>`:empty('No schedules yet','Schedule platform assurance, captured-evidence review, or a blocked readiness check. Actual probes are added with the bank adapter.')}</div>`:''}${measurementPanels(captures)}`}

function measurementPanels(captures){
 const f=state.measurementFilters||{connection:'',operation:''};
 const name=id=>id==='imported'?'Imported responses':state.workspace.connections.find(c=>c.id===id)?.name||id;
 const ids=[...new Set(captures.map(r=>r.connectionId||'imported'))];
 const selected=captures.filter(r=>!f.connection||(r.connectionId||'imported')===f.connection);
 const rows=selected.flatMap(r=>(r.metrics||[]).filter(m=>m.attempts&&(!f.operation||m.operation===f.operation)).map(m=>({r,m})));
 const imported=selected.filter(r=>r.evidenceMode!=='mock_http'&&(r.metrics||[]).some(m=>m.attempts&&(!f.operation||m.operation===f.operation)));
 const select=(id,label,values,value)=>'<div class="field"><label for="'+id+'">'+label+'</label><select id="'+id+'"><option value="">All '+label.toLowerCase()+'s</option>'+values.map(([v,t])=>'<option value="'+e(v)+'" '+(value===v?'selected':'')+'>'+e(t)+'</option>').join('')+'</select></div>';
 const section=(id,title,count,content)=>'<details class="card space measurement-section" data-measurement-section="'+id+'" '+(state.measurementCollapsed?.[id]?'':'open')+'><summary><span>'+title+'</span><span class="badge">'+count+'</span>'+icon('chevron')+'</summary><div class="measurement-scroll" tabindex="0" role="region" aria-label="'+title+'">'+content+'</div></details>';
 const table=rows.length?'<table><thead><tr><th>Connection / run</th><th>Profile / mode</th><th>Operation</th><th>Attempts</th><th>p50 ms</th><th>p95 ms</th></tr></thead><tbody>'+rows.map(({r,m})=>'<tr><td>'+e(name(r.connectionId||'imported'))+'<small>'+e(r.name)+'</small></td><td>'+e(r.profile)+'<small>'+e(r.evidenceMode)+'</small></td><td>'+e(m.operation)+'</td><td>'+m.attempts+'</td><td>'+e(m.p50??'—')+'</td><td>'+e(m.p95??'Insufficient samples')+'</td></tr>').join('')+'</tbody></table>':empty(captures.length?'No measurements match these filters':'No response measurements yet',captures.length?'Change or reset the filters.':'Run a configured bank audit or import timestamped response samples.');
 return '<div class="measurement-filters card pad space">'+select('measurement-connection','Connection',ids.map(id=>[id,name(id)]),f.connection)+select('measurement-operation','Operation',['accounts','balances','transactions','consent'].map(op=>[op,op[0].toUpperCase()+op.slice(1)]),f.operation)+button('Reset filters','reset-measurements','quiet')+'</div>'+section('responses','Response measurements by connection',rows.length+' measurements',table)+section('imports','Imported measurement reports',imported.length+' reports',imported.length?runTable(imported):empty('No imported reports match','Import timestamped response samples or change the filters.'));
}

function reports(){const runs=state.workspace.runs.filter(r=>r.status==='completed');return head('ACTIONABLE OUTPUTS','Reports','Findings, quality and synthetic availability reports with disclosed observation coverage.')+availabilityPanel()+`<div class="grid two"><div class="card report-card">${icon('reports')}<h2>Incompatibility report</h2><p>Expected vs observed, selected rule, source locator, impact, remediation guidance and evidence mode. Platform checks stay separate from bank findings.</p><div class="chip-list"><span class="chip">Source-linked</span><span class="chip">Printable HTML / PDF</span><span class="chip">JSON export</span></div></div><div class="card report-card">${icon('monitor')}<h2>Quality report</h2><p>Per-operation counts, failure categories, p50 and p95. Small samples and missing measurements remain visible. Thresholds are not configured.</p><div class="chip-list"><span class="chip">Raw sample CSV</span><span class="chip">Measurement method</span><span class="chip">Observation coverage</span></div></div></div><div class="card space"><div class="card-head"><h2>Available report bundles</h2></div>${runs.length?`<div class="table-wrap"><table><thead><tr><th>Run</th><th>Evidence mode</th><th>Reports</th></tr></thead><tbody>${runs.map(r=>`<tr><td><b>${e(r.name)}</b><small>${date(r.finishedAt)}</small></td><td>${badge(r.evidenceMode)}</td><td><div class="buttons">${exportLink(r.id,'incompatibility','Findings')}${exportLink(r.id,'quality','Quality')}${exportLink(r.id,'json','JSON')}${canRun()?exportLink(r.id,'csv','CSV'):''}</div></td></tr>`).join('')}</tbody></table></div>`:empty('No reports available','Complete an audit to generate findings and quality reports.',canRun()?button('Run bank API audit','new-run','primary'):'')}</div>`}
const exportLink=(id,type,label)=>`<a class="btn small" href="/api/runs/${e(id)}/export/${type}" target="_blank" rel="noopener">${icon('download')}${label}</a>`;
function standards(){const w=state.workspace;const governanceSummary=canReview()?`<div class="grid three space">${metric('Rules awaiting review',w.rules.filter(r=>r.status==='draft').length,'Read source conditions before approving','standards')}${metric('Approved rules',w.rules.filter(r=>r.status==='approved').length,'Versioned reviewer decisions','check')}${metric('Reference documents',w.sources.length,'Open exact Georgian source text','reports')}</div>`:'';return head('VERSIONED SOURCES · REVIEWED EXPECTATIONS',canReview()?'Standards & rules':'Applicable standards & rules','Source documents inform candidate checks. Human review controls activation.',canReview()?button(icon('plus')+' Compare source snapshot','source-update'):'')+governanceSummary+notice('Profile applicability','The uploaded index points payment-account AIS to XS2A 0.8.RC3. Newer AIS and consent rules are not automatically applied to payment accounts.')+`<div class="grid three space">${w.profiles.map(p=>`<div class="card pad"><h3>${e(p.name)}</h3>${badge(p.status)}<p class="smalltext" style="margin-top:12px">${e(p.note)}</p></div>`).join('')}</div><div class="card space"><div class="card-head"><div><h2>Rules and review status</h2><p>Review each rule, its source, and applicability before approving it.</p></div><span class="subtle">${w.rules.filter(r=>r.status==='approved').length} approved · ${w.rules.filter(r=>r.status==='draft').length} draft</span></div>${w.rules.map(r=>`<div class="rule-row"><div><h3>${e(r.id)} · ${e(r.title)}</h3><p>${e(r.profile)} · §${e(r.section)} · ${e(r.reviewNote)}</p></div><div class="buttons">${badge(r.status)}${button('Inspect','review-rule','small',`data-id="${r.id}"`)}</div></div>`).join('')}</div><h2 class="space">Reference documents</h2><div class="grid two space">${w.sources.map(s=>`<div class="card source-card"><h3>${e(s.name)}</h3><div class="mono">SHA-256 ${e(s.sha256)}</div><a class="btn small" target="_blank" rel="noopener" href="/api/sources?file=${encodeURIComponent(s.file)}">Open extracted source ${icon('arrow')}</a></div>`).join('')}</div>${w.updates.length?`<div class="card space"><div class="card-head"><h2>Proposed source changes</h2></div>${w.updates.map(x=>`<div class="pad"><h3>${e(x.title)} ${badge(x.status)}</h3><p>${e(x.notice)}</p><p class="smalltext">${(x.added||[]).length} added lines · ${(x.removed||[]).length} removed lines · ${(x.affectedRules||[]).length} candidate rules affected</p><details class="space"><summary>Inspect text diff</summary><pre class="code light">${e((x.added||[]).map(x=>'+ '+x).join('\n')+'\n'+(x.removed||[]).map(x=>'- '+x).join('\n'))}</pre></details></div>`).join('')}</div>`:''}`}
function gates(){const w=state.workspace;return head('REGRESSIONS BEFORE PUBLICATION','Release gates','Evaluate a candidate against a completed run. Incomplete bank coverage holds publication.',canRun()?button('Compare specifications','spec-diff')+button(icon('plus')+' Evaluate candidate','new-gate','primary'):'')+notice('Release decision criteria','Failed checks reject a candidate. Missing bank evidence puts it on hold. Decisions apply to GeoBridge records and do not deploy or block external bank changes.')+`<div class="card space"><div class="card-head"><h2>Candidate decisions</h2></div>${w.gates.length?`<div class="table-wrap"><table><thead><tr><th>Candidate</th><th>Decision</th><th>Reason</th><th>Time</th></tr></thead><tbody>${w.gates.map(g=>`<tr><td><b>${e(g.name)}</b><small>${e(String(g.runId||'').slice(0,8))}</small></td><td>${badge(g.decision)}</td><td>${e(g.reason)}</td><td>${date(g.at)}</td></tr>`).join('')}</tbody></table></div>`:empty('No release candidates evaluated','Complete an audit, then evaluate a candidate using its results. Bank approval requires bank evidence.')}</div>`}
function detail(){const r=state.run;if(!r)return empty('Loading run','Fetching persisted evidence…');const counts=r.counts||{};return head('PERSISTED AUDIT EVIDENCE',e(r.name),`${e(r.profile)} · Created ${date(r.createdAt)}`,`<div class="buttons">${button(state.run.kind==='platform'?'← System diagnostics':'← Audit history',state.run.kind==='platform'?'nav-diagnostics':'nav-audit')}${canRun()?button('Retest','retest','primary',`data-id="${r.id}"`):''}</div>`)+`<div class="card"><div class="result-banner"><div><h2>${badge(r.status)} <span class="subtle">${e(r.id)}</span></h2><p>${e(r.evidenceMode||r.kind)} · ${r.finishedAt?'Finished '+date(r.finishedAt):'Waiting for worker result'}</p></div>${['queued','running'].includes(r.status)&&canRun()?button('Stop run','stop-run','danger',`data-id="${r.id}"`):''}</div>${['queued','running'].includes(r.status)?'<div class="loading-line"></div>':''}</div>${r.error?`<div class="notice amber space">${e(r.error)}</div>`:''}<div class="mini-stat">${['PASS','FAIL','BLOCKED','NEEDS_REVIEW','NOT_ASSESSED','NOT_APPLICABLE'].map(k=>`<div><b>${counts[k]||0}</b>${badge(k)}</div>`).join('')}</div>${notice('Result scope','Local platform checks validate GeoBridge controls. Imported fixtures and uploaded captures are not live bank tests. Passing selected checks is not overall compliance.')}<div class="tabs space"><button class="tab ${state.filter==='all'?'active':''}" data-filter="all">All checks</button>${['compatibility','reliability','latency','security'].map(l=>`<button class="tab ${state.filter===l?'active':''}" data-filter="${l}">${l[0].toUpperCase()+l.slice(1)}</button>`).join('')}<button class="tab ${state.filter==='metrics'?'active':''}" data-filter="metrics">Quality metrics</button></div>${state.filter==='metrics'?metricDetail(r):`<div class="card">${r.results?.filter(f=>state.filter==='all'||f.layer===state.filter).map(f=>`<div class="finding" data-finding="${e(f.id)}"><div style="color:var(--teal)">${icon(f.layer==='security'?'gate':'audit')}</div><div><h3>${e(f.title)}</h3><p>${e(f.observed)}</p><small class="subtle">${e(f.ruleId||f.id)} · ${e(f.basis||'Selected rule')}${f.section?' · §'+e(f.section):''}</small></div>${badge(f.verdict)}</div>`).join('')||empty('No results in this layer','The worker has not recorded any matching checks.')}</div>`}${r.status==='completed'?`<div class="buttons space">${exportLink(r.id,'incompatibility','Incompatibility report')}${exportLink(r.id,'quality','Quality report')}${exportLink(r.id,'json','Run JSON')}${canRun()?exportLink(r.id,'csv','Sample CSV'):''}</div><div class="card pad space"><h3>Run metadata</h3><p class="mono">Ruleset ${e(r.rulesetHash)}<br>Evidence ${e(r.evidenceHash||'Local platform controls; no bank response')}<br>Build ${e(r.build)}</p><p class="footnote">${(r.limitations||[]).map(e).join('<br>')}</p></div>`:''}`}
function metricDetail(r){return `<div class="card"><div class="card-head"><div><h2>Per-operation quality</h2><p>Successful positive-request timings only. No regulatory threshold configured.</p></div></div>${r.metrics?.some(m=>m.attempts)?`<div class="table-wrap"><table><thead><tr><th>Operation</th><th>Attempts</th><th>Success</th><th>Errors</th><th>Timeouts</th><th>p50</th><th>p95</th></tr></thead><tbody>${r.metrics.map(m=>`<tr><td>${e(m.operation)}</td><td>${m.attempts}</td><td>${m.successRate===null?'—':(m.successRate*100).toFixed(1)+'%'}</td><td>${m.errors}</td><td>${m.timeouts}</td><td>${m.p50===null?'—':m.p50+' ms'}</td><td>${m.p95===null?'Insufficient samples':m.p95+' ms'}</td></tr>`).join('')}</tbody></table></div>`:empty('No bank latency measurements','Internal test execution duration is not bank response time. Import timestamped measurement samples or connect a bank adapter.')}</div>`}
function render(){if(!state.user)return login();if(!policy().pages.includes(state.page)&&!(state.page==='detail'&&state.run&&(state.run.kind==='platform'?state.user.role==='operator':policy().pages.includes('audit'))))state.page=policy().home;const views={overview,audit,connections,explorer,oversight,monitor:monitoring,reports,standards,gate:gates,detail,diagnostics};if(state.page==='activity'){shell(head('WHO · WHAT · WHEN','Activity log','Permission-scoped events recorded by the backend.')+'<div id="activity-list" class="card">'+empty('Loading events','Retrieving the audit trail…')+'</div>');loadEvents().catch(err=>toast(err.message));return}shell((views[state.page]||overview)())}
async function loadEvents(){const rows=await api('/api/events');const el=document.querySelector('#activity-list');if(el)el.innerHTML=rows.length?`<div class="table-wrap"><table><thead><tr><th>Action</th><th>Actor</th><th>Target</th><th>When</th></tr></thead><tbody>${rows.map(r=>`<tr><td>${e(r.action.replaceAll('_',' '))}</td><td>${e(r.actor)}</td><td class="mono">${e(r.target)}</td><td>${date(r.at)}</td></tr>`).join('')}</tbody></table></div>`:empty('No visible events','Events appear as you use the workspace.')}
async function showRun(id){state.run=await api('/api/runs/'+id);state.page='detail';state.filter='all';state.menuOpen=false;render();globalThis.window?.scrollTo({top:0,left:0,behavior:'instant'})}
async function startRun(body){const r=await api(body.kind==='platform'?'/api/diagnostics':'/api/runs',{method:'POST',body});dialog.close();await refresh();await showRun(r.id)}
function newRun(){modal('Run bank API audit',`<p>Choose a bank connection. Readiness is checked before any audit is queued.</p><div class="field"><label for="run-connection">Bank connection</label><select id="run-connection"><option value="">Select a connection</option>${state.workspace.connections.map(c=>`<option value="${e(c.id)}">${e(c.name)}${c.synthetic?' (mock)':''}</option>`).join('')}</select></div><div id="bank-readiness" role="status" aria-live="polite"></div><div class="buttons space">${button('Run bank API audit','execute-run','primary')}</div>`)}
function reviewSaved(){modal('Review saved API responses',`<p>Review stored responses against selected rules. This does not send requests to a bank.</p><div class="field"><label for="run-pack">Saved response set</label><select id="run-pack"><option value="">Select saved responses</option>${state.workspace.packs.map(p=>`<option value="${e(p.id)}">${e(p.name)} · ${e(p.mode)}</option>`).join('')}</select></div><div class="buttons">${button('Review selected responses','execute-saved','primary')}${button('Import responses','import-evidence')}</div>`)}
async function runBankAudit(connectionId,control){
 if(!connectionId)throw Error('Select a bank connection.');
 if(control)control.disabled=true;
 try{const readiness=await api('/api/connections/'+encodeURIComponent(connectionId)+'/readiness');
 if(!readiness.ready){const message=readiness.reasons.map(r=>r.message).join(' '),out=document.querySelector('#bank-readiness');if(dialog.open&&out){out.innerHTML=notice('Connection is not ready',readiness.reasons.map(r=>e(r.message)).join('<br>'),true)}else toast(message);return}
 await startRun({kind:'bank',connectionId});
 }finally{if(control)control.disabled=false}
}
async function signOut(){
 if(state.busy)return;state.busy=true;
 const screen=document.createElement('div');screen.className='session-transition';screen.setAttribute('role','status');screen.innerHTML='<div><span class="login-dots" aria-hidden="true"><i></i><i></i><i></i></span><p>Signing out…</p></div>';document.body.appendChild(screen);
 try{await Promise.all([api('/api/logout',{method:'POST'}),new Promise(resolve=>setTimeout(resolve,450))]);clearSession();login();globalThis.window?.scrollTo({top:0,left:0,behavior:'instant'})}
 catch(err){toast(err.message)}finally{screen.remove();state.busy=false}
}
function importEvidence(){modal('Import synthetic response evidence',`<p>Use the documented JSON format. Credentials and common identifiers are redacted before persistence.</p><div class="field"><label for="evidence-file">JSON file</label><input type="file" accept=".json,application/json" id="evidence-file"></div><div class="field"><label for="evidence-json">Evidence pack JSON</label><textarea id="evidence-json" style="min-height:230px" placeholder="Paste JSON or load the fictional example"></textarea></div><label class="check"><input type="checkbox" id="synthetic-confirm">I confirm all data is synthetic and the evidence mode accurately identifies fixtures or sandbox captures.</label><div class="buttons">${button('Load fictional example','load-example')}${button('Import evidence','save-evidence','primary')}</div><p class="footnote">The example has no timing samples. We do not manufacture performance results.</p>`)}
async function findingDetail(id){const r=state.run,f=r.results.find(x=>x.id===id);let raw='';if(canRun()&&r.packId&&f.observationIndex!==undefined){const p=await api('/api/packs/'+r.packId);raw=JSON.stringify(p.observations[f.observationIndex],null,2)}modal('Finding details',`<h3>${e(f.title)} ${badge(f.verdict)}</h3><p class="mono">${e(f.ruleId||f.id)} · ${e(f.basis||'Selected rule')} · ${e(r.evidenceMode)}</p><div class="detail-grid space"><div class="detail-block"><label>Expected</label>${e(f.expected)}</div><div class="detail-block"><label>Observed</label>${e(f.observed)}</div><div class="detail-block full"><label>Suggested action</label>${e(f.fix||'Review the recorded control assertions. Retest after any relevant implementation change.')}</div></div>${f.quote?`<div class="quote">${e(f.quote)}</div><p class="smalltext">${e(f.source)} · §${e(f.section)} · ${e(f.reviewNote)}</p>`:''}${raw?`<details class="space"><summary>Original redacted evidence</summary><pre class="code">${e(raw)}</pre></details>`:''}<div class="divider"></div><h3>Explanation assistance</h3><p class="smalltext">Verdicts stay deterministic. AI advice is bounded and may be incorrect.</p><div class="buttons space">${button('Explain in English','explain','small',`data-id="${e(f.id)}" data-language="en"`)}${button('განმარტება ქართულად','explain','small',`data-id="${e(f.id)}" data-language="ka"`)}</div><div id="explanation-result"></div><p class="footnote">Reproduce: select this run’s evidence pack and profile, then Retest. Raw sample CSV is available from the run.</p>`)}
async function reviewRule(id){const r=state.workspace.rules.find(x=>x.id===id);modal('Review source and applicability',`<h3>${e(r.id)} · ${e(r.title)} ${badge(r.status)}</h3><p class="smalltext">${e(r.profile)} · ${e(r.source)} · §${e(r.section)}</p>${r.bankApplicability?`<p class="smalltext">Applies to: ${e(r.bankApplicability.join(', '))} · Legacy payment-account AIS only</p>`:''}<div class="quote">${e(r.quote)}</div><p>${e(r.fix)}</p>${r.references?`<div class="source-reference-links">${r.references.map(ref=>`<a class="btn small" href="${e(ref.url)}" target="_blank" rel="noopener">${e(ref.label)} ${icon('arrow')}</a>`).join('')}</div>`:''}<p class="footnote">${e(r.reviewNote)}<br>Source hash: ${e(r.sourceHash)}</p><a class="btn small space" target="_blank" rel="noopener" href="/api/sources?file=${encodeURIComponent(r.source)}">Read full source ${icon('arrow')}</a>${canReview()?`<div class="field"><label for="review-note">Reviewer applicability note</label><textarea id="review-note" placeholder="Record the account category, selected service, mandatory/conditional nature and observed assertion being approved."></textarea></div><label class="check"><input type="checkbox" id="review-confirm">I reviewed the source and conditions. This approval covers only the implemented observable assertion, not full legal compliance.</label><div class="buttons">${button('Approve rule','approve-rule','primary',`data-id="${r.id}"`)}${button('Keep as draft','draft-rule','',`data-id="${r.id}"`)}</div>`:notice('Reviewer access required','Use a standards reviewer account to approve executable rules.')}`)}
document.addEventListener('change',async ev=>{if(ev.target.id==='measurement-connection'||ev.target.id==='measurement-operation'){state.measurementFilters={...(state.measurementFilters||{connection:'',operation:''}),[ev.target.id==='measurement-connection'?'connection':'operation']:ev.target.value};render();document.querySelector('#'+ev.target.id)?.focus();return}if(ev.target.id==='mobile-nav'){navigate(ev.target.value)}if(ev.target.id==='mapping-operation'){document.querySelector('#mapping-json').value=JSON.stringify(mappingSamples[ev.target.value],null,2)}if(ev.target.id==='evidence-file'){const f=ev.target.files[0];if(f){if(f.size>2e6)return toast('File exceeds 2 MB');document.querySelector('#evidence-json').value=await f.text()}}});
document.addEventListener('click',async ev=>{const el=ev.target.closest('[data-action],[data-nav],[data-run],[data-filter],[data-finding]');if(!el)return;try{
 if(el.dataset.nav){return navigate(el.dataset.nav)}if(el.dataset.run)return await showRun(el.dataset.run);if(el.dataset.filter){state.filter=el.dataset.filter;return render()}if(el.dataset.finding)return await findingDetail(el.dataset.finding);
 const a=el.dataset.action;if(a==='reset-measurements'){state.measurementFilters={connection:'',operation:''};render();return}if(a==='toggle-menu'||a==='close-menu'){setMenu(a==='toggle-menu'&&!state.menuOpen);return}if(a.startsWith('nav-')){return navigate(a.slice(4))}if(a==='close')return dialog.close();if(a==='refresh')return await refresh();if(a==='logout')return await signOut();
 if(a==='compare-runs'){const rs=state.workspace.runs.filter(r=>r.status==='completed');const opts=rs.map(r=>`<option value="${r.id}">${e(r.name)} · ${date(r.finishedAt)}</option>`).join('');return modal('Compare equivalent audit runs',`<p>Choose the same profile and evidence mode. Changed rulesets and evidence hashes remain visible.</p><div class="field"><label for="compare-before">Before</label><select id="compare-before">${opts}</select></div><div class="field"><label for="compare-after">After</label><select id="compare-after">${opts}</select></div>${button('Compare verdicts','compare-execute','primary')}<div id="compare-result"></div>`)}
 if(a==='compare-execute'){const x=await api('/api/compare',{method:'POST',body:{before:document.querySelector('#compare-before').value,after:document.querySelector('#compare-after').value}});document.querySelector('#compare-result').innerHTML='<pre class="code space">'+e(JSON.stringify(x,null,2))+'</pre>';return}
 if(a==='spec-diff')return modal('Compare candidate OpenAPI specifications',`<p>Structural diff only. No external deployment or automatic normative inference.</p><div class="field"><label for="spec-before">Baseline OpenAPI JSON</label><textarea id="spec-before"></textarea></div><div class="field"><label for="spec-after">Candidate OpenAPI JSON</label><textarea id="spec-after"></textarea></div>${button('Compare endpoints','spec-diff-execute','primary')}<div id="spec-diff-result"></div>`);
 if(a==='spec-diff-execute'){const x=await api('/api/spec-diff',{method:'POST',body:{before:JSON.parse(document.querySelector('#spec-before').value),after:JSON.parse(document.querySelector('#spec-after').value)}});document.querySelector('#spec-diff-result').innerHTML='<pre class="code space">'+e(JSON.stringify(x,null,2))+'</pre>';return}

 if(a==='availability-refresh'){await refresh();return}
 if(a==='availability-config'){
  const t=(state.availability||[]).find(t=>t.id===el.dataset.id),r=t.report;
  return modal('Configure synthetic availability monitoring',`<p>Checks GET /api/health, not all bank operations. Monitoring continues while the backend is running, including during an outage.</p><label class="check"><input id="availability-enabled" type="checkbox" ${r.enabled?'checked':''}> Enable monitoring</label><div class="field"><label>Probe interval (seconds)</label><input id="availability-interval" type="number" min="5" max="3600" value="${r.intervalSeconds}"></div><div class="field"><label>Absolute deadline (seconds)</label><input id="availability-timeout" type="number" min="1" max="10" value="${r.timeoutSeconds}"></div>${button('Save','availability-save','primary',`data-id="${e(t.id)}"`)}`);
 }
 if(a==='availability-save'){await api('/api/availability/'+el.dataset.id+'/configure',{method:'POST',body:{enabled:document.querySelector('#availability-enabled').checked,intervalSeconds:Number(document.querySelector('#availability-interval').value),timeoutSeconds:Number(document.querySelector('#availability-timeout').value)}});dialog.close();await refresh();return}
 if(a==='availability-switch'){if(!confirm(el.dataset.online==='true'?'Restore synthetic API responses?':'Stop synthetic API responses? Monitoring will continue and record failures.'))return;el.disabled=true;try{await api('/api/availability/'+el.dataset.id+'/switch',{method:'POST',body:{online:el.dataset.online==='true'}});toast('Mock switch applied. Observed status changes after the next probe.');await refresh()}finally{el.disabled=false}return}
 if(a==='availability-probe'){await api('/api/availability/'+el.dataset.id+'/probe',{method:'POST',body:{}});await refresh();return}
 if(a==='availability-report'){
  const r=await api('/api/availability/'+el.dataset.id+'/report');
  return modal('Availability report · '+e(r.name),`<p>SYNTHETIC · ${e(r.probe)}</p><p>Window: ${date(r.window.from)} – ${date(r.window.to)}</p><p>Successful checks: ${pct(r.successfulChecksPercent)} (${r.successes}/${r.checks}) · Estimated uptime in covered intervals: ${pct(r.estimatedUptimePercent)} · Coverage: ${pct(r.coveragePercent)}</p><p>Estimated down: ${duration(r.estimatedDownMs)} · Unknown/unobserved: ${duration(r.unknownMs)}</p><h3>Detected incidents</h3>${r.incidents.length?'<div class="table-wrap"><table><thead><tr><th>Detected</th><th>Last success</th><th>Recovered</th><th>Duration from detection</th></tr></thead><tbody>'+r.incidents.map(i=>'<tr><td>'+date(i.detectedAt)+'</td><td>'+date(i.lastSuccessfulAt)+'</td><td>'+(i.endedAt?date(i.endedAt):i.interrupted?'Observation interrupted':'No recovery observed')+'</td><td>'+(i.estimatedDurationMs===undefined?'Unknown/open':duration(i.estimatedDurationMs))+'</td></tr>').join('')+'</tbody></table></div>':'<p>No incidents observed in this window.</p>'}<h3>Recent probes</h3><div class="table-wrap"><table><thead><tr><th>Time</th><th>Result</th><th>HTTP</th><th>Duration</th></tr></thead><tbody>${r.recentSamples.slice().reverse().map(p=>'<tr><td>'+date(p.at)+'</td><td>'+e(p.outcome)+'</td><td>'+e(p.httpStatus??'No response')+'</td><td>'+p.durationMs+' ms</td></tr>').join('')}</tbody></table></div><ul>${r.limitations.map(l=>'<li>'+e(l)+'</li>').join('')}</ul><div class="buttons"><a class="btn" href="/api/availability/${e(r.id)}/report?format=json" target="_blank" rel="noopener">Export JSON</a><a class="btn" href="/api/availability/${e(r.id)}/report?format=csv">Export CSV</a></div>`);
 }

 if(a==='gringott-consent'){
  el.disabled=true;try{const cid=document.querySelector('#gringott-connection').value;const x=await api('/bridge/v1/connections/'+cid+'/consents',{method:'POST',body:{}});state.gringott={connection:cid,...x};render();toast('Synthetic consent granted. Tokens stay on the server.')}finally{el.disabled=false}return;
 }
 if(a==='gringott-revoke'){
  const s=state.gringott;try{await api('/bridge/v1/connections/'+s.connection+'/consents/'+s.consentId,{method:'DELETE'});}finally{state.gringott=null;render()}return;
 }
 if(a==='gringott-request'){
  const s=state.gringott;if(!s)throw Error('Grant simulated consent first');
  const operation=document.querySelector('#gringott-operation').value,account=document.querySelector('#gringott-account').value;
  const route='/bridge/v1/connections/'+s.connection+'/accounts'+(operation==='accounts'?'':'/'+encodeURIComponent(account)+'/'+operation);
  const out=document.querySelector('#gringott-response');el.disabled=true;
  try{const x=await api(route,{headers:{'Consent-ID':s.consentId}});out.textContent=JSON.stringify(x,null,2)}catch(err){out.textContent=err.message}finally{el.disabled=false}return;
 }
 if(a==='new-run')return newRun();if(a==='run-platform')return await startRun({kind:'platform'});if(a==='review-saved')return reviewSaved();if(a==='execute-saved'){const packId=document.querySelector('#run-pack').value;if(!packId)throw Error('Select saved responses.');el.disabled=true;try{return await startRun({kind:'evidence',packId})}finally{el.disabled=false}}if(a==='execute-run')return await runBankAudit(document.querySelector('#run-connection').value,el);
 if(a==='run-spec')return await startRun({kind:'spec',connectionId:el.dataset.id});if(a==='readiness')return await runBankAudit(el.dataset.id,el);if(a==='retest'){const r=state.run;if(r.kind==='bank')return await runBankAudit(r.connectionId,el);return await startRun({kind:r.kind,packId:r.packId,connectionId:r.connectionId})}
 if(a==='stop-run'){await api('/api/runs/'+el.dataset.id+'/stop',{method:'POST'});await showRun(el.dataset.id);return}
 if(a==='import-evidence')return importEvidence();if(a==='load-example'){document.querySelector('#evidence-json').value=JSON.stringify(await api('/api/example'),null,2);return}
 if(a==='save-evidence'){if(!document.querySelector('#synthetic-confirm').checked)throw Error('Confirm synthetic data first');const b=JSON.parse(document.querySelector('#evidence-json').value);const result=await api('/api/packs',{method:'POST',body:b});dialog.close();await refresh();toast('Responses imported. Select them in Review saved API responses.');return}
 if(a==='normalize'){const b=JSON.parse(document.querySelector('#mapping-json').value);const result=await api('/api/normalize',{method:'POST',body:{synthetic:true,operation:document.querySelector('#mapping-operation').value,body:b}});document.querySelector('#mapping-result').innerHTML=badge('Validated','pass')+'<pre class="code space">'+e(JSON.stringify(result,null,2))+'</pre>';return}
 if(a==='mapping-fault'){const b=structuredClone(mappingSamples.balances);delete b.balances[0].balanceAmount.currency;document.querySelector('#mapping-operation').value='balances';document.querySelector('#mapping-json').value=JSON.stringify(b,null,2);return}
 if(a==='bridge-check'){try{const x=await api('/bridge/v1/connections/pending/accounts');document.querySelector('#bridge-result').innerHTML='<pre class="code">'+e(JSON.stringify(x,null,2))+'</pre>'}catch(err){document.querySelector('#bridge-result').innerHTML='<div class="notice amber space">'+e(err.message)+'</div>'}return}
 if(a==='new-connection')return modal('Register a sandbox connection',`<p>Registration stores metadata only. External targets also require an operator-configured host allowlist.</p><div class="field"><label for="connection-name">Connection name</label><input id="connection-name" placeholder="Assigned sandbox A"></div><div class="field"><label for="connection-profile">Applicable profile</label><select id="connection-profile">${state.workspace.profiles.filter(p=>p.id!=='platform').map(p=>`<option value="${p.id}">${e(p.name)}</option>`).join('')}</select></div><div class="field"><label for="connection-url">Sandbox HTTPS base URL (optional until supplied)</label><input id="connection-url" placeholder="https://sandbox.example"></div>${button('Register connection','save-connection','primary')}`);
 if(a==='save-connection'){await api('/api/connections',{method:'POST',body:{name:document.querySelector('#connection-name').value,profile:document.querySelector('#connection-profile').value,baseUrl:document.querySelector('#connection-url').value}});dialog.close();await refresh();return toast('Connection registered; connectivity remains unverified')}
 if(a==='upload-spec')return modal('Upload OpenAPI JSON',`<p>Remote references are not fetched. No secrets should be included.</p><div class="field"><label for="spec-json">OpenAPI 3 JSON</label><textarea id="spec-json" placeholder='{"openapi":"3.0.3","info":{},"paths":{}}'></textarea></div>${button('Save specification','save-spec','primary',`data-id="${el.dataset.id}"`)}`);
 if(a==='save-spec'){const x=await api('/api/connections/'+el.dataset.id+'/spec',{method:'POST',body:{spec:JSON.parse(document.querySelector('#spec-json').value)}});dialog.close();await refresh();toast(x.notice);if(x.runId)await showRun(x.runId);return}
 if(a==='review-rule')return await reviewRule(el.dataset.id);
 if(['approve-rule','draft-rule'].includes(a)){await api('/api/rules/'+el.dataset.id+'/review',{method:'POST',body:{approve:a==='approve-rule',confirm:document.querySelector('#review-confirm').checked,note:document.querySelector('#review-note').value}});dialog.close();await refresh();return toast('Rule review recorded')}
 if(a==='explain'){el.disabled=true;try{const x=await api('/api/runs/'+state.run.id+'/explain',{method:'POST',body:{findingId:el.dataset.id,language:el.dataset.language}});document.querySelector('#explanation-result').innerHTML=`<div class="detail-block space"><label>${e(x.mode.replaceAll('_',' '))}${x.cached?' · cached':''}</label><p>${e(x.summary)}</p><p style="margin-top:10px">${e(x.impact)}</p><p style="margin-top:10px">${e(x.fix)}</p><small>${e(x.reason||x.reviewStatus||'')} · ${date(x.generatedAt)}</small></div>`}finally{el.disabled=false}return}
 if(a==='new-schedule')return modal('Schedule an audit job',`<p>The local server must remain running. Uploaded evidence reviews are replays, not new bank measurements.</p><div class="field"><label for="schedule-kind">Job</label><select id="schedule-kind"><option value="evidence">Review imported evidence</option><option value="bank">Audit configured mock / check unconnected sandbox</option></select></div><div class="field"><label for="schedule-pack">Evidence pack</label><select id="schedule-pack"><option value="">Select</option>${state.workspace.packs.map(p=>`<option value="${p.id}">${e(p.name)}</option>`).join('')}</select></div><div class="field"><label for="schedule-connection">Connection</label><select id="schedule-connection">${state.workspace.connections.map(c=>`<option value="${c.id}">${e(c.name)}</option>`).join('')}</select></div><div class="field"><label for="schedule-minutes">Interval in minutes</label><input id="schedule-minutes" type="number" min="1" max="1440" value="60"></div>${button('Create schedule','save-schedule','primary')}`);
 if(a==='save-schedule'){await api('/api/schedules',{method:'POST',body:{kind:document.querySelector('#schedule-kind').value,packId:document.querySelector('#schedule-pack').value,connectionId:document.querySelector('#schedule-connection').value,minutes:Number(document.querySelector('#schedule-minutes').value)}});dialog.close();await refresh();return toast('Schedule created')}
 if(a==='delete-schedule'){await api('/api/schedules/'+el.dataset.id,{method:'DELETE'});return await refresh()}
 if(a==='new-gate')return modal('Evaluate a release candidate',`<p>This records a publication decision; it does not deploy or modify an external API.</p><div class="field"><label for="gate-name">Candidate name</label><input id="gate-name" placeholder="Adapter 0.1.0 candidate"></div><div class="field"><label for="gate-run">Completed evidence run</label><select id="gate-run"><option value="">Select a run</option>${state.workspace.runs.filter(r=>r.status==='completed').map(r=>`<option value="${r.id}">${e(r.name)} · ${date(r.finishedAt)}</option>`).join('')}</select></div>${button('Evaluate gate','save-gate','primary')}`);
 if(a==='save-gate'){const x=await api('/api/gates',{method:'POST',body:{name:document.querySelector('#gate-name').value,runId:document.querySelector('#gate-run').value}});dialog.close();await refresh();return toast(x.decision+': '+x.reason)}
 if(a==='source-update')return modal('Compare a candidate source snapshot',`<p>Text differences are proposals only. No new rule or mandate is automatically activated.</p><div class="field"><label for="update-title">Comparison label</label><input id="update-title" placeholder="Historical or simulated comparison"></div><div class="field"><label for="update-source">Pinned baseline</label><select id="update-source">${state.workspace.sources.map(s=>`<option value="${s.id}">${e(s.name)}</option>`).join('')}</select></div><div class="field"><label for="update-text">Candidate extracted text</label><textarea id="update-text"></textarea></div>${button('Compare snapshots','save-update','primary')}`);
 if(a==='save-update'){await api('/api/updates',{method:'POST',body:{title:document.querySelector('#update-title').value,sourceId:document.querySelector('#update-source').value,text:document.querySelector('#update-text').value}});dialog.close();await refresh();return toast('Draft comparison saved; rule activation still requires review')}
 }catch(err){if(el.dataset.action==='normalize'){const out=document.querySelector('#mapping-result');if(out)out.innerHTML=badge('Contract violation','fail')+`<div class="notice amber space">${e(err.message)}</div>`}toast(err.message)}});
dialog.addEventListener('click',ev=>{if(ev.target===dialog)dialog.close()});
setInterval(async()=>{if(state.user&&state.page==='detail'&&state.run&&['queued','running'].includes(state.run.status)&&!dialog.open){try{state.run=await api('/api/runs/'+state.run.id);if(state.run.status==='completed')state.workspace=await api('/api/workspace');render()}catch{}}},1300);
try{const result=await api('/api/me');activateSession(result);await refresh()}catch(err){if(state.user)toast('Workspace could not load: '+err.message);else login()}

function pct(v){return v===null||v===undefined?'Not measured':v.toFixed(2)+'%'}
function gringottExplorer(){
 const connections=(state.workspace.catalog||[]).filter(c=>c.capabilities?.accounts==='mock_supported');
 if(!connections.length)return '';
 const s=state.gringott;
 return `<div class="card space"><div class="card-head"><div><h2>Mock bank API requests</h2><p>Actual HTTP calls through the selected bank adapter. Simulated consent only; no official bank connected.</p></div>${badge('mock_http')}</div><div class="pad"><div class="field"><label>Configured connection</label><select id="gringott-connection" ${s?'disabled':''}>${connections.map(c=>`<option value="${e(c.id)}" ${s?.connection===c.id?'selected':''}>${e(c.name)}</option>`).join('')}</select></div>${s?`<p>Consent expires ${date(s.expiresAt)}. Workspace refresh preserves this tab’s consent reference; server restart requires new consent.</p><div class="field"><label>Operation</label><select id="gringott-operation"><option value="accounts">Accounts</option><option value="balances">Balances</option><option value="transactions">All transaction pages</option></select></div><div class="field"><label>Account (balances / transactions)</label><select id="gringott-account">${s.accounts.map(a=>`<option value="${e(a.accountId)}">${e(a.accountId)} · ${e(a.currency)}</option>`).join('')}</select></div><div class="buttons">${button('Send request','gringott-request','primary')}${button('Revoke consent','gringott-revoke')}</div><pre class="code space" id="gringott-response">Choose an operation.</pre>`:button('Grant simulated consent','gringott-consent','primary')}<p class="footnote">Tokens are held only in server memory. To collect evidence and findings, run a mock HTTP audit from Connections or Audit center.</p></div></div>`;
}
function duration(ms){return (ms/1000).toFixed(1)+' s'}
function availabilityPanel(){const targets=state.availability||[];return '<div class="card space"><div class="card-head"><div><h2>Synthetic API availability</h2><p>Health probes, recovery detection and persisted incident reports. Default report window: last 24 hours.</p></div>'+button('Refresh','availability-refresh','small')+'</div><div class="pad">'+(targets.length?targets.map(t=>{const r=t.report;return '<div class="detail-block space"><h3>'+e(t.name)+' '+badge(r.currentStatus,r.currentStatus==='up'?'pass':r.currentStatus==='down'?'fail':'unknown')+'</h3><p>Successful checks '+pct(r.successfulChecksPercent)+' · Estimated uptime '+pct(r.estimatedUptimePercent)+' · Coverage '+pct(r.coveragePercent)+'</p><p>'+r.checks+' probes · Estimated down '+duration(r.estimatedDownMs)+' · Unknown '+duration(r.unknownMs)+' · Last check '+date(r.lastCheck?.at)+'</p><div class="buttons">'+button('Report & export','availability-report','small','data-id="'+e(t.id)+'"')+(canRun()?button('Configure','availability-config','small','data-id="'+e(t.id)+'"')+button('Probe now','availability-probe','small','data-id="'+e(t.id)+'"'):'')+(t.canSwitch?button('API OFF (timeout)','availability-switch','small','data-id="'+e(t.id)+'" data-online="false"')+button('API ON','availability-switch','small','data-id="'+e(t.id)+'" data-online="true"'):'')+'</div></div>'}).join(''):'<p>No synthetic targets configured by the server operator. Existing readiness schedules do not collect availability measurements.</p>')+'</div></div>'}
setInterval(async()=>{if(state.user&&state.page==='monitor'&&!dialog.open){try{const x=await api('/api/availability');if(state.user&&state.page==='monitor'){state.availability=x.targets||[];render()}}catch{}}},5000);

document.addEventListener('toggle',ev=>{const key=ev.target.dataset?.measurementSection;if(key)state.measurementCollapsed={...state.measurementCollapsed,[key]:!ev.target.open}},true);
